import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    for record in records:
        if record:
            record[0] = record[0].lstrip("\ufeff")

    header_index = None
    for index, record in enumerate(records):
        if len(record) == expected_width and sum(bool(value.strip()) for value in record) >= 2:
            header_index = index
            break

    if header_index is None:
        header_index = next((i for i, row in enumerate(records) if row), 0)

    columns = list(records[header_index])
    if not columns:
        columns = [f"column_{i + 1}" for i in range(expected_width)]

    width = len(columns)
    rows = []
    for record in records[header_index + 1:]:
        row = list(record)
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
